const input = $json.body ?? $json;
const clean = (value) => String(value ?? '').trim();
const digits = (value) => clean(value).replace(/[^0-9+]/g, '');
const email = clean(input.email).toLowerCase();
const phone = digits(input.whatsappNumber || input.phone);
const requestSeed = `${Date.now()}-${phone.replace(/\D/g, '').slice(-6) || 'demo'}`;
return [{ json: { requestId: `QF-${requestSeed}`, contact: { fullName: clean(input.fullName || input.name), email, whatsappNumber: phone, preferredChannel: 'Both', consent: input.consent === true || clean(input.consent).toLowerCase() === 'true' }, job: { serviceType: clean(input.serviceType), propertyType: clean(input.propertyType), serviceAddress: clean(input.serviceAddress), serviceArea: clean(input.serviceArea), propertySize: clean(input.propertySize), cleaningFrequency: clean(input.cleaningFrequency), preferredDate: clean(input.preferredDate), specialRequirements: clean(input.specialRequirements), estimatedValue: Number(input.estimatedValue || 0) }, context: { source: clean(input.source || 'Website form'), customerEngaged: input.customerEngaged === true, receivedAt: new Date().toISOString() } } }];

const data = $json;
const required = [
  ['full name', data.contact.fullName],
  ['email address', data.contact.email],
  ['WhatsApp number', data.contact.whatsappNumber],
  ['service type', data.job.serviceType],
  ['property type', data.job.propertyType],
  ['service address', data.job.serviceAddress],
  ['service area or postcode', data.job.serviceArea],
  ['property size', data.job.propertySize],
  ['cleaning frequency', data.job.cleaningFrequency],
  ['preferred date', data.job.preferredDate]
];
const missingFields = required.filter(([, value]) => !String(value ?? '').trim()).map(([label]) => label);
const invalidFields = [];
if (data.contact.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.contact.email)) invalidFields.push('email address');
if (data.contact.whatsappNumber && data.contact.whatsappNumber.replace(/\D/g, '').length < 8) invalidFields.push('WhatsApp number');
return [{ json: { ...data, validation: { isComplete: missingFields.length === 0 && invalidFields.length === 0, missingFields, invalidFields } } }];

const data = $json;
const reasons = [];
let score = 0;
if (data.job.serviceArea) { score += 20; reasons.push('service area supplied'); }
if (data.validation.isComplete) { score += 15; reasons.push('complete request'); }
if (/weekly|fortnight|monthly|recurr/i.test(data.job.cleaningFrequency)) { score += 20; reasons.push('recurring service'); }
if (data.job.estimatedValue >= 500) { score += 20; reasons.push('strong estimated value'); }
else if (data.job.estimatedValue >= 250) { score += 10; reasons.push('moderate estimated value'); }
if (data.job.preferredDate) { score += 15; reasons.push('workable date supplied'); }
if (data.context.customerEngaged) { score += 10; reasons.push('customer engaged'); }
const stage = data.validation.isComplete ? (score >= 40 ? 'Qualified' : 'Manual Review') : 'Awaiting Information';
const priority = score >= 70 ? 'Hot' : score >= 40 ? 'Warm' : 'Review';
const nextAction = new Date(Date.now() + (data.validation.isComplete ? 24 : 6) * 60 * 60 * 1000).toISOString();
return [{ json: { ...data, qualification: { score, priority, reasons, stage }, controls: { followUpCount: 0, stopFollowUps: false, nextActionAt: nextAction } } }];

const data = $json;
const firstName = data.contact.fullName.split(/\s+/)[0] || 'there';
const acknowledgement = `Hi ${firstName}, thanks for requesting a quote from BrightNest Cleaning. We received your ${data.job.serviceType || 'cleaning'} request. Your reference is ${data.requestId}.`;
const missing = [...data.validation.missingFields, ...data.validation.invalidFields];
const missingRequest = missing.length ? `Hi ${firstName}, we are preparing your cleaning quote and need: ${missing.join(', ')}. Reply with those details and we will continue your request.` : '';
const nextMessage = missingRequest || `Hi ${firstName}, your request is ready for review. We will send available inspection times shortly.`;
return [{ json: { ...data, communications: { email: { to: data.contact.email, subject: `Cleaning quote request received - ${data.requestId}`, body: `${acknowledgement}\n\n${nextMessage}` }, whatsapp: { to: data.contact.whatsappNumber, templateKey: missing.length ? 'quote_missing_information' : 'quote_acknowledgement', body: `${acknowledgement} ${nextMessage}` } } } }];
